hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "V", function()
	local cmd = "alacritty --class clippick -e /home/krishnan/.local/bin/clippick"
	local win = hl.get_active_window()
	if win then
		cmd = cmd .. " --paste-to address:" .. win.address .. " '" .. paste_mods(win) .. "'"
	end
	hl.exec_cmd(cmd)
end)
