-- APPLICATION SWITCHER
-- Focuses the sole matching window directly via hl.get_windows/hl.dsp.focus;
-- falls back to the sway-app-switcher script (tofi picker) when 0 or 2+ match.
local function bind_app_switch(key, class_name, fallback_args)
	hl.bind(key, function()
		local windows = hl.get_windows({ class = class_name })
		if #windows == 1 then
			hl.dispatch(hl.dsp.focus({ window = "address:" .. windows[1].address }))
		else
			hl.exec_cmd("sway-app-switcher " .. fallback_args)
		end
	end)
end

